class Solution {
    public int maxNonDecreasingLength(int[] nums1, int[] nums2) {
        int a = 1, b = 1, ans = 1;
        for (int i = 1; i < nums1.length; i++) {
            int na = 1 + Math.max(nums1[i-1] <= nums1[i] ? a : 0, nums2[i-1] <= nums1[i] ? b : 0);
            int nb = 1 + Math.max(nums1[i-1] <= nums2[i] ? a : 0, nums2[i-1] <= nums2[i] ? b : 0);
            a = na; b = nb;
            ans = Math.max(ans, Math.max(a, b));
        }
        return ans;
    }
}

